async function setupConfig() {
	const configureDatabases = require('../install/databases');

	// prompt prepends "prompt: " to questions, let's clear that.
	prompt.start();
	prompt.message = '';
	prompt.delimiter = '';
	prompt.colors = false;
	let config = {};

	if (install.values) {
		// Use provided values, fall back to defaults
		const redisQuestions = require('./database/redis').questions;
		const mongoQuestions = require('./database/mongo').questions;
		const postgresQuestions = require('./database/postgres').questions;
		const allQuestions = [
			...questions.main,
			...questions.optional,
			...redisQuestions,
			...mongoQuestions,
			...postgresQuestions,
		];

		allQuestions.forEach((question) => {
			if (install.values.hasOwnProperty(question.name)) {
				config[question.name] = install.values[question.name];
			} else if (question.hasOwnProperty('default')) {
				config[question.name] = question.default;
			} else {
				config[question.name] = undefined;
			}
		});
	} else {
		config = await prompt.get(questions.main);
	}
	await configureDatabases(config);
	await completeConfigSetup(config);
}

async function completeConfigSetup(config) {
	// Add CI object
	if (install.ciVals) {
		config.test_database = { ...install.ciVals };
	}

	// Add package_manager object if set
	if (nconf.get('package_manager')) {
		config.package_manager = nconf.get('package_manager');
	}

	if (install.values.hasOwnProperty('saas_plan')) {
		config.saas_plan = install.values.saas_plan;
	}

	nconf.overrides(config);
	const db = require('./database');
	await db.init();
	if (db.hasOwnProperty('createIndices')) {
		await db.createIndices();
	}

	// Sanity-check/fix url/port
	if (!/^http(?:s)?:\/\//.test(config.url)) {
		config.url = `http://${config.url}`;
	}

	// If port is explicitly passed via install vars, use it. Otherwise, glean from url if set.
	const urlObj = url.parse(config.url);
	if (urlObj.port && (!install.values || !install.values.hasOwnProperty('port'))) {
		config.port = urlObj.port;
	}

	// Remove trailing slash from non-subfolder installs
	if (urlObj.path === '/') {
		urlObj.path = '';
		urlObj.pathname = '';
	}

	config.url = url.format(urlObj);

	// ref: https://github.com/indexzero/nconf/issues/300
	delete config.type;

	setupPageRoute(app, '/ip-blacklist', [], controllers.globalMods.ipBlacklist);
	setupPageRoute(app, '/registration-queue', [], controllers.globalMods.registrationQueue);
};

_mounts.topic = (app, name, middleware, controllers) => {
	setupPageRoute(app, `/${name}/:topic_id/:slug/:post_index?`, [], controllers.topics.get);
	setupPageRoute(app, `/${name}/:topic_id/:slug?`, [], controllers.topics.get);
};

_mounts.post = (app, name, middleware, controllers) => {
	const middlewares = [
		middleware.maintenanceMode,
		middleware.authenticateRequest,
		middleware.registrationComplete,
		middleware.pluginHooks,
	];
	app.get(`/${name}/:pid`, middleware.busyCheck, middlewares, controllers.posts.redirectToPost);
	app.get(`/api/${name}/:pid`, middlewares, controllers.posts.redirectToPost);
};

_mounts.tags = (app, name, middleware, controllers) => {
	setupPageRoute(app, `/${name}/:tag`, [middleware.privateTagListing], controllers.tags.getTag);
	setupPageRoute(app, `/${name}`, [middleware.privateTagListing], controllers.tags.getTags);
};
_mounts.categories = (app, name, middleware, controllers) => {
	setupPageRoute(app, '/categories', [], controllers.categories.list);
	setupPageRoute(app, '/popular', [], controllers.popular.get);
	setupPageRoute(app, '/recent', [], controllers.recent.get);
	setupPageRoute(app, '/top', [], controllers.top.get);
	setupPageRoute(app, '/unread', [middleware.ensureLoggedIn], controllers.unread.get);
};

_mounts.category = (app, name, middleware, controllers) => {
	setupPageRoute(app, `/${name}/:category_id/:slug/:topic_index`, [], controllers.category.get);
	setupPageRoute(app, `/${name}/:category_id/:slug?`, [], controllers.category.get);
};
